// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));
        uint256 amount = 1 ether;
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore > 0, "setup failed: contract must have balance");

        vm.prank(nonOwner);
        try c.withdrawAll() {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore);
        } catch {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}
